begin;
create table if not exists public.hwarang_learning_work (
 user_id uuid not null references public.profiles(id), content_id text not null references public.hwarang_learning_content(id),
 revision integer not null, lesson_id text not null, version integer not null default 1,
 answers jsonb not null default '{}', practice text not null default '', score integer,
 status text not null default 'draft' check(status in ('draft','submitted','revision_requested','approved')),
 feedback jsonb not null default '{}', reviewer_id uuid references public.profiles(id), reviewed_at timestamptz,
 updated_at timestamptz not null default now(), primary key(user_id,content_id,revision,lesson_id)
);
alter table public.hwarang_learning_work enable row level security;
revoke all on public.hwarang_learning_work from public,anon,authenticated;
grant select,insert,update on public.hwarang_learning_work to service_role;
create index if not exists hwarang_learning_work_queue on public.hwarang_learning_work(content_id,status,user_id);

create or replace function public.hwarang_learning_work_get(p_actor uuid,p_id text,p_target uuid default null)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare target uuid:=coalesce(p_target,p_actor); d jsonb;
begin
 perform private.learning_check(p_actor);
 if target<>p_actor and not private.can_user_view(p_actor,target) then raise exception 'LEARNING_ACCESS_DENIED';end if;
 select data into d from public.hwarang_learning_content where id=p_id;
 if d is null or not coalesce((d->>'published')::boolean,false) then raise exception 'LEARNING_ACCESS_DENIED';end if;
 if target=p_actor and not exists(select 1 from public.get_hwarang_effective_permissions(p_actor) where permission_code=d->>'permission') then raise exception 'LEARNING_ACCESS_DENIED';end if;
 return coalesce((select jsonb_agg(to_jsonb(w) order by lesson_id) from public.hwarang_learning_work w where user_id=target and content_id=p_id and revision=(d->>'revision')::integer),'[]');
end $$;

create or replace function public.hwarang_learning_work_save(p_actor uuid,p_id text,p_revision integer,p_lesson text,p_version integer,p_answers jsonb,p_practice text,p_submit boolean)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare d jsonb;l jsonb;q jsonb; w public.hwarang_learning_work; correct integer:=0; total integer; result_score integer; result_status text;
begin
 perform private.learning_check(p_actor);
 select data into d from public.hwarang_learning_content where id=p_id for share;
 if d is null or d->>'learning_mode' is distinct from 'practice' or not coalesce((d->>'published')::boolean,false) or not exists(select 1 from public.get_hwarang_effective_permissions(p_actor) where permission_code=d->>'permission') then raise exception 'LEARNING_ACCESS_DENIED';end if;
 if (d->>'revision')::integer is distinct from p_revision then raise exception 'CONTENT_CHANGED_RELOAD';end if;
 select x into l from jsonb_array_elements(d->'lessons') x where x->>'id'=p_lesson;
 if l is null then raise exception 'INVALID_LESSON';end if;
 if p_submit is null or p_version is null or p_version<0 or jsonb_typeof(p_answers) is distinct from 'object' or octet_length(p_answers::text)>10000 or p_practice is null or length(p_practice)>5000 then raise exception 'INVALID_INPUT';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text||p_id||p_revision::text||p_lesson,20261030));
 select * into w from public.hwarang_learning_work where user_id=p_actor and content_id=p_id and revision=p_revision and lesson_id=p_lesson for update;
 if coalesce(w.version,0)<>p_version then raise exception 'WORK_CHANGED_RELOAD';end if;
 if w.status='approved' then raise exception 'APPROVED_WORK_LOCKED';end if;
 if w.status='submitted' then raise exception 'SUBMITTED_WORK_LOCKED';end if;
 result_status:='draft';
 if p_submit then
  if length(trim(p_practice))<30 then raise exception 'PRACTICE_TOO_SHORT';end if;
  total:=jsonb_array_length(l->'quiz');
  if coalesce(total,0)=0 then raise exception 'QUIZ_NOT_READY';end if;
  for q in select * from jsonb_array_elements(l->'quiz') loop
   if p_answers->>(q->>'id')=q->>'answer' then correct:=correct+1;end if;
  end loop;
  result_score:=round(100.0*correct/total);
  if result_score<coalesce((d->>'pass_percent')::integer,100) then
   return jsonb_build_object('passed',false,'score',result_score,'version',coalesce(w.version,0));
  end if;
  result_status:='submitted';
 end if;
 insert into public.hwarang_learning_work(user_id,content_id,revision,lesson_id,version,answers,practice,score,status)
 values(p_actor,p_id,p_revision,p_lesson,p_version+1,p_answers,trim(p_practice),result_score,result_status)
 on conflict(user_id,content_id,revision,lesson_id) do update set version=excluded.version,answers=excluded.answers,practice=excluded.practice,score=excluded.score,status=excluded.status,updated_at=now();
 if p_submit then
  insert into public.hwarang_learning_progress(user_id,content_id,revision,completed_lessons) values(p_actor,p_id,p_revision,array[p_lesson])
  on conflict(user_id,content_id) do update set revision=p_revision,completed_lessons=case when hwarang_learning_progress.revision<>p_revision then array[p_lesson] else array(select distinct unnest(hwarang_learning_progress.completed_lessons||array[p_lesson])) end,updated_at=now();
 end if;
 return jsonb_build_object('passed',p_submit,'score',result_score,'version',p_version+1,'status',result_status);
end $$;

create or replace function public.hwarang_learning_work_review(p_actor uuid,p_target uuid,p_id text,p_revision integer,p_lesson text,p_version integer,p_approve boolean,p_feedback jsonb)
returns void language plpgsql security invoker set search_path='' as $$
declare w public.hwarang_learning_work; d jsonb;
begin
 perform private.learning_check(p_actor);
 if p_actor=p_target or not private.can_user_view(p_actor,p_target) then raise exception 'LEARNING_ACCESS_DENIED';end if;
 if p_approve is null or jsonb_typeof(p_feedback) is distinct from 'object' or octet_length(p_feedback::text)>6000 or coalesce(length(trim(p_feedback->>'good')),0)<1 or coalesce(length(trim(p_feedback->>'improve')),0)<1 or coalesce(length(trim(p_feedback->>'next')),0)<1 then raise exception 'FEEDBACK_REQUIRED';end if;
 select data into d from public.hwarang_learning_content where id=p_id;
 if (d->>'revision')::integer is distinct from p_revision or not coalesce((d->>'published')::boolean,false) then raise exception 'CONTENT_CHANGED_RELOAD';end if;
 select * into w from public.hwarang_learning_work where user_id=p_target and content_id=p_id and revision=p_revision and lesson_id=p_lesson for update;
 if w.version is distinct from p_version or w.status is distinct from 'submitted' then raise exception 'WORK_CHANGED_RELOAD';end if;
 update public.hwarang_learning_work set status=case when p_approve then 'approved' else 'revision_requested' end,feedback=p_feedback,reviewer_id=p_actor,reviewed_at=now(),version=version+1,updated_at=now() where user_id=p_target and content_id=p_id and revision=p_revision and lesson_id=p_lesson;
 if not p_approve then update public.hwarang_learning_progress set completed_lessons=array_remove(completed_lessons,p_lesson),updated_at=now() where user_id=p_target and content_id=p_id and revision=p_revision;end if;
end $$;

create or replace function public.hwarang_learning_team(p_actor uuid,p_id text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare d jsonb;
begin
 perform private.learning_check(p_actor);
 select data into d from public.hwarang_learning_content where id=p_id;
 if d is null or d->>'learning_mode' is distinct from 'practice' or not coalesce((d->>'published')::boolean,false) then raise exception 'LEARNING_ACCESS_DENIED';end if;
 return coalesce((select jsonb_agg(to_jsonb(t) order by t.display_name) from (
  select p.id user_id,p.display_name,p.position_code,coalesce(o.name,'소속 미지정') organization,
   coalesce((select count(*) from public.hwarang_learning_work w where w.user_id=p.id and w.content_id=p_id and w.revision=(d->>'revision')::integer and w.status in ('submitted','approved')),0) completed,
   coalesce((select count(*) from public.hwarang_learning_work w where w.user_id=p.id and w.content_id=p_id and w.revision=(d->>'revision')::integer and w.status='submitted' and exists(select 1 from jsonb_array_elements(d->'lessons') l where l->>'id'=w.lesson_id and (l->>'mentor_required')::boolean)),0) waiting,
   coalesce((select count(*) from public.hwarang_learning_work w where w.user_id=p.id and w.content_id=p_id and w.revision=(d->>'revision')::integer and w.status='approved' and exists(select 1 from jsonb_array_elements(d->'lessons') l where l->>'id'=w.lesson_id and (l->>'mentor_required')::boolean)),0) approved,
   (select max(updated_at) from public.hwarang_learning_work w where w.user_id=p.id and w.content_id=p_id) last_activity
  from public.profiles p left join public.organization_units o on o.id=p.organization_unit_id
  where p.is_active and p.id<>p_actor and private.can_user_view(p_actor,p.id)
   and exists(select 1 from public.hwarang_app_access a where a.user_id=p.id and a.app_code='academy' and a.is_enabled)
   and exists(select 1 from public.get_hwarang_effective_permissions(p.id) e where e.permission_code=d->>'permission')
 )t),'[]');
end $$;

revoke all on function public.hwarang_learning_work_get(uuid,text,uuid),public.hwarang_learning_work_save(uuid,text,integer,text,integer,jsonb,text,boolean),public.hwarang_learning_work_review(uuid,uuid,text,integer,text,integer,boolean,jsonb),public.hwarang_learning_team(uuid,text) from public,anon,authenticated;
grant execute on function public.hwarang_learning_work_get(uuid,text,uuid),public.hwarang_learning_work_save(uuid,text,integer,text,integer,jsonb,text,boolean),public.hwarang_learning_work_review(uuid,uuid,text,integer,text,integer,boolean,jsonb),public.hwarang_learning_team(uuid,text) to service_role;
create or replace function public.hwarang_learning_complete(p_actor uuid,p_id text,p_revision integer,p_lesson text)
returns void language plpgsql security invoker set search_path='' as $$
declare d jsonb;
begin
 perform private.learning_check(p_actor);
 select data into d from public.hwarang_learning_content where id=p_id for share;
 if d is null or not coalesce((d->>'published')::boolean,false) or not exists(select 1 from public.get_hwarang_effective_permissions(p_actor) where permission_code=d->>'permission') then raise exception 'LEARNING_ACCESS_DENIED'; end if;
 if d->>'learning_mode'='practice' then raise exception 'USE_PRACTICE_SUBMISSION';end if;
 if (d->>'revision')::integer<>p_revision then raise exception 'CONTENT_CHANGED_RELOAD';end if;
 if not exists(select 1 from jsonb_array_elements(d->'lessons') x where x->>'id'=p_lesson) then raise exception 'INVALID_LESSON';end if;
 insert into public.hwarang_learning_progress(user_id,content_id,revision,completed_lessons) values(p_actor,p_id,p_revision,array[p_lesson])
 on conflict(user_id,content_id) do update set revision=p_revision,
 completed_lessons=case when hwarang_learning_progress.revision<>p_revision then array[p_lesson] else array(select distinct unnest(hwarang_learning_progress.completed_lessons||array[p_lesson])) end,updated_at=now();
end $$;

insert into public.hwarang_learning_content(id,data) values('newhire-30-v1','{"id": "newhire-30-v1", "kind": "course", "category": "new_hire", "permission": "academy.new_hire", "title": "신입 공통 과정 · 첫 30일", "summary": "하루 30분 기본 학습 · 60분 집중 학습 · 주간 실습과 피드백", "body": "", "lessons": [{"id": "d01", "day": 1, "title": "첫 30일의 목표와 업무 준비", "scenario": "일을 시작하면 무엇부터 해야 하나요?", "body": "규정집과 현재 지점 운영 안내의 위치를 확인합니다. 계정·명함·전산 권한·자격 준비 상태를 체크하고 미완료 항목의 담당자와 날짜를 정합니다. 수당률·승격·파트너·시책 조건은 소속과 적용 월의 공식 안내로 확인합니다. 학습 일정의 1일차는 시작 순서이며 매일 출석을 강제하는 달력이 아닙니다.", "flow": ["규정 확인", "계정 준비", "자격 계획", "첫 달 목표"], "practice": "첫 달에 할 수 있게 될 업무 3개와 도움받을 담당자·일정을 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "계정 준비가 끝나지 않았다면?", "options": ["담당자와 필요한 권한·처리 일정을 확인한다", "다른 직원 계정을 빌린다"], "answer": 0, "explanation": "담당자와 필요한 권한·처리 일정을 확인한다. 규정집과 현재 지점 운영 안내의 위치를 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d02", "day": 2, "title": "비즈니스 매너와 첫인사", "scenario": "처음 만나는 고객이 바빠 보입니다.", "body": "시간과 장소를 미리 확인하고 준비 자료를 정돈합니다. 자신과 소속을 밝힌 뒤 지금 대화가 가능한지 묻습니다. 명함은 상대가 읽기 편하게 건네고 선호하는 호칭을 확인합니다. 자리를 임의로 지정하기보다 고객이 편한 곳을 선택하게 합니다. 매너는 고객을 재촉하지 않고 약속을 지키는 행동으로 보여줍니다.", "flow": ["약속 확인", "소개와 인사", "대화 동의", "고객의 속도"], "practice": "자기소개, 대화 가능 여부, 상담 목적을 포함한 30초 인사말을 작성하세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "고객이 지금 통화가 어렵다고 하면?", "options": ["상품 설명부터 끝낸다", "편한 연락 시간과 재연락 의사를 확인한다"], "answer": 1, "explanation": "편한 연락 시간과 재연락 의사를 확인한다. 시간과 장소를 미리 확인하고 준비 자료를 정돈합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 신입교육 비지니스 매너.pptx · 질문·경청·역할극 재구성"]}, {"id": "d03", "day": 3, "title": "고객 상담의 7단계", "scenario": "보험이 많은데 무엇이 필요한지 모르겠어요.", "body": "관계 형성·연락과 약속·첫 상담·사실 확인·대안 비교·계약 확인·사후관리의 목적을 구분합니다. 회사에서 쓰는 TA·AP·FF·PC·CS·RL 명칭은 담당자와 대응시킵니다. 첫 만남에서 고객이 원하는 결과를 묻고 자료가 준비된 뒤 분석합니다. 고객이 원하지 않으면 중단하거나 다음 약속을 합의합니다.", "flow": ["연락·약속", "첫 상담·확인", "비교·선택", "계약·사후관리"], "practice": "각 상담 단계에서 고객과 합의할 행동을 한 문장씩 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "현재 계약을 모르는 첫 만남에서 먼저 할 일은?", "options": ["고객의 고민과 확인할 자료를 정한다", "교체할 상품부터 정한다"], "answer": 0, "explanation": "고객의 고민과 확인할 자료를 정한다. 관계 형성·연락과 약속·첫 상담·사실 확인·대안 비교·계약 확인·사후관리의 목적을 구분합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 신입교육 비지니스 매너.pptx · 질문·경청·역할극 재구성"]}, {"id": "d04", "day": 4, "title": "계약자·피보험자·수익자", "scenario": "보험료를 내는 사람이 보험금도 받나요?", "body": "계약자는 계약의 당사자, 피보험자는 보장 대상인 사람, 수익자는 해당 보험금을 받도록 정한 사람입니다. 세 역할은 같을 수도 다를 수도 있습니다. 어머니가 계약하고 자녀를 보장해도 수익자는 증권에서 따로 확인합니다. 보험료를 실제 납입하는 계좌의 명의만으로 세 역할을 추정하지 않습니다.", "flow": ["계약자: 계약", "피보험자: 보장 대상", "수익자: 수령"], "practice": "가상 가족 계약을 만들고 세 역할과 추가 확인할 항목을 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "계약자와 피보험자만 알 때 수익자는?", "options": ["보험료를 낸 사람으로 정한다", "해당 보험금의 수익자 지정 내용을 확인한다"], "answer": 1, "explanation": "해당 보험금의 수익자 지정 내용을 확인한다. 계약자는 계약의 당사자, 피보험자는 보장 대상인 사람, 수익자는 해당 보험금을 받도록 정한 사람입니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d05", "day": 5, "title": "보험료·보험금·보장기간", "scenario": "월 5만 원이면 천만 원을 받는 건가요?", "body": "보험료는 납입하는 금액, 가입금액은 담보별 기준 금액, 보험금은 조건을 충족했을 때 지급하는 금액입니다. 납입기간과 보장기간도 분리해 읽습니다. 20년 납입·90세 만기라는 가상 계약은 두 기간의 뜻이 다르다는 연습이며 실제 상품 조건을 뜻하지 않습니다. 가입금액만 보고 지급을 확약하지 않습니다.", "flow": ["납입 금액", "담보별 기준", "지급 조건", "두 가지 기간"], "practice": "가상 증권의 보험료, 납입기간, 보장기간, 가입금액을 각각 설명하세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "가입금액 1천만 원을 발견했다면?", "options": ["지급 사유와 감액·제외 조건도 확인한다", "모든 사고에 1천만 원을 약속한다"], "answer": 0, "explanation": "지급 사유와 감액·제외 조건도 확인한다. 보험료는 납입하는 금액, 가입금액은 담보별 기준 금액, 보험금은 조건을 충족했을 때 지급하는 금액입니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d06", "day": 6, "title": "전산·고객등록과 개인정보", "scenario": "고객 자료를 단체 채팅방에 올려도 될까요?", "body": "등록 목적과 필요한 항목, 회사의 동의·보관 절차를 먼저 확인합니다. 계정과 비밀번호를 공유하지 않고 고객 자료는 승인된 경로로만 전달합니다. 교육 실습에는 가상 고객을 사용합니다. 전산 화면을 연습할 때 실제 주민번호·진료기록을 붙여 넣지 않습니다. 모바일팩스도 수신처와 회사 승인 여부를 확인한 뒤 사용합니다.", "flow": ["목적 확인", "필요 범위", "승인된 전달", "보관·삭제"], "practice": "사용할 전산과 고객등록 절차, 자료 전송 전 확인 항목을 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "교육 실습에 사용할 자료로 적절한 것은?", "options": ["고객 진단서 원본 전체", "실제 개인정보가 없는 가상 사례"], "answer": 1, "explanation": "실제 개인정보가 없는 가상 사례. 등록 목적과 필요한 항목, 회사의 동의·보관 절차를 먼저 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d07", "day": 7, "title": "1주차 실습과 시작 면담", "scenario": "처음 만난 고객에게 상담 목적을 설명해 보세요.", "body": "첫인사 후 상담 가능 시간을 확인합니다. 고객의 궁금한 점을 열린 질문으로 묻고 들은 내용을 한 번 요약합니다. 필요한 자료와 다음 일정을 합의합니다. 선배는 잘한 행동, 빠진 확인, 다음 연습을 각각 하나씩 피드백합니다. 아직 모르는 상품의 지급 여부를 질문받으면 확인 후 답할 시간을 약속합니다.", "flow": ["인사", "열린 질문", "요약", "다음 약속"], "practice": "첫 상담 대본과 선배에게 확인받고 싶은 점을 제출하세요. 팀장 검토가 필요한 주간 실습입니다.", "mentor_required": true, "quiz": [{"id": "q1", "question": "모르는 보장을 질문받았을 때는?", "options": ["확인이 필요한 이유와 답변 일정을 안내한다", "신뢰를 위해 확실하다고 답한다"], "answer": 0, "explanation": "확인이 필요한 이유와 답변 일정을 안내한다. 첫인사 후 상담 가능 시간을 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d08", "day": 8, "title": "목표와 프로스펙팅", "scenario": "연락할 사람은 많지만 무엇을 제안할지 모르겠어요.", "body": "관계를 고객의 필요와 연결해 생각합니다. 실명 명단을 교육란에 옮기지 말고 가상 유형으로 분류합니다. 연락 가능 여부, 예상 관심, 도움이 될 이유를 적습니다. 월간 계획에는 통제할 수 있는 행동과 검토 시간을 넣습니다. 계약 건수만 목표로 삼으면 확인과 사후관리의 질을 놓치기 쉽습니다.", "flow": ["관심 파악", "도움의 이유", "연락 동의", "행동 계획"], "practice": "가상 고객 유형 3개와 각 유형에 도움이 될 질문, 이번 주 행동 계획을 작성하세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "연락 계획에 먼저 넣을 것은?", "options": ["확인되지 않은 재산 규모", "상대의 필요와 연락 가능 여부"], "answer": 1, "explanation": "상대의 필요와 연락 가능 여부. 관계를 고객의 필요와 연결해 생각합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d09", "day": 9, "title": "TA와 이관 고객 첫 연락", "scenario": "담당자가 바뀌었다는데 누구세요?", "body": "자신과 소속, 담당 변경을 확인할 수 있는 방법, 연락 목적을 짧게 설명합니다. 고객이 본인 확인을 원하면 공식 경로를 안내합니다. 통화 중 바로 민감 정보를 요구하지 않습니다. 거절하면 이유를 억지로 캐묻지 않고 재연락 의사를 확인합니다. 이관 경위와 연락 가능 범위는 회사 기록으로 먼저 확인합니다.", "flow": ["소속 소개", "변경 사실 확인", "목적", "시간 합의"], "practice": "이관 고객 첫 연락 40초 대본과 바쁜 고객에게 남길 짧은 문자를 작성하세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "이관 고객이 신원을 의심하면?", "options": ["공식 확인 경로를 안내한다", "주민번호를 요청해 신원을 확인한다"], "answer": 0, "explanation": "공식 확인 경로를 안내한다. 자신과 소속, 담당 변경을 확인할 수 있는 방법, 연락 목적을 짧게 설명합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 신입교육 비지니스 매너.pptx · 질문·경청·역할극 재구성"]}, {"id": "d10", "day": 10, "title": "질문·경청과 니즈 확인", "scenario": "보험료도 줄이고 보장은 더 갖고 싶어요.", "body": "고객이 원하는 결과를 묻고 예산, 유지하고 싶은 보장, 불편했던 경험을 차례로 확인합니다. 민감한 질문은 이유를 설명하고 동의를 구합니다. 고객 말과 자신의 해석을 구분해 요약합니다. 결론을 빨리 정하기보다 서로 충돌하는 요구의 우선순위를 확인합니다.", "flow": ["목표 질문", "사실 확인", "우선순위", "요약 확인"], "practice": "가상 고객의 요구를 확인할 질문 4개와 마지막 요약 문장을 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "두 요구가 충돌할 때는?", "options": ["설계사가 임의로 우선순위를 정한다", "고객이 더 중요하게 생각하는 기준을 확인한다"], "answer": 1, "explanation": "고객이 더 중요하게 생각하는 기준을 확인한다. 고객이 원하는 결과를 묻고 예산, 유지하고 싶은 보장, 불편했던 경험을 차례로 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 신입교육 비지니스 매너.pptx · 질문·경청·역할극 재구성"]}, {"id": "d11", "day": 11, "title": "알릴 의무와 일반·간편 심사", "scenario": "간편보험이면 병력을 말하지 않아도 되나요?", "body": "일반심사와 간편심사는 질문 항목과 범위가 다를 수 있습니다. 실제 청약서의 질문과 기간을 읽고 고객이 사실대로 답하도록 안내합니다. 설계사가 병력을 임의로 생략하거나 대신 판단하지 않습니다. 애매한 진료 이력은 승인된 절차로 보험사에 확인하고 확인 경위를 남깁니다. 구두 전달만으로 필요한 절차가 모두 끝났다고 단정하지 않습니다.", "flow": ["실제 질문", "기간·범위", "고객의 사실 답변", "추가 확인"], "practice": "진료 사실이 애매한 가상 고객에게 할 안내와 보험사에 확인할 질문을 작성하세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "간편심사 상품을 설명할 때는?", "options": ["그 상품의 질문과 기간을 실제로 확인한다", "모든 병력 고지가 면제된다고 설명한다"], "answer": 0, "explanation": "그 상품의 질문과 기간을 실제로 확인한다. 일반심사와 간편심사는 질문 항목과 범위가 다를 수 있습니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d12", "day": 12, "title": "청약 확인과 설명 책임", "scenario": "서류가 많으니 대신 체크해 주실래요?", "body": "고객이 이해하고 본인 의사로 진행하는지 확인합니다. 보장 내용과 제외·감액, 보험료와 기간, 해지 시 불이익 등 중요한 조건을 상품 자료에 근거해 설명합니다. 서명·동의·서류 교부는 회사의 최신 절차에 맞춥니다. 등록·자격과 취급 권한이 갖춰지기 전에는 권한 밖의 업무를 진행하지 않습니다.", "flow": ["설명", "이해 확인", "본인 의사", "서류 확인"], "practice": "청약 전 확인할 질문 5개와 고객이 이해했는지 확인하는 말을 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "고객의 서명을 대신 부탁받으면?", "options": ["편의를 위해 대신 서명한다", "본인 확인과 회사 절차에 맞게 진행한다"], "answer": 1, "explanation": "본인 확인과 회사 절차에 맞게 진행한다. 고객이 이해하고 본인 의사로 진행하는지 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d13", "day": 13, "title": "공시실과 약관 찾기", "scenario": "같은 상품 이름인데 조건이 달라요.", "body": "보험사·상품명·가입 시기·특약명을 먼저 확인합니다. 현재 판매 중인 상품의 약관이 과거 계약과 같다고 가정하지 않습니다. 보험사 공시실에서 해당 시점 자료를 찾고 보장 정의, 지급 조건, 제외 사항, 용어 정의를 함께 읽습니다. 찾지 못하면 설계매니저나 보험사에 정확한 계약 정보를 제시해 요청합니다.", "flow": ["회사·상품", "가입 시기", "특약·정의", "지급·제외"], "practice": "가상 계약의 약관을 찾는 검색 조건과 확인할 조항 목록을 작성하세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "과거 계약의 조건을 확인할 자료는?", "options": ["그 계약 시점과 특약에 해당하는 약관", "현재 광고 화면만 사용"], "answer": 0, "explanation": "그 계약 시점과 특약에 해당하는 약관. 보험사·상품명·가입 시기·특약명을 먼저 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d14", "day": 14, "title": "2주차 실습: 연락부터 약속까지", "scenario": "고객은 보험료가 부담되지만 상담을 망설입니다.", "body": "첫 연락에서 소개와 목적을 밝히고, 거절 이유가 시간인지 필요성인지 확인합니다. 상담이 가능하면 고객의 관심에 맞춰 준비 자료를 설명하고 날짜·시간·방식을 합의합니다. 동료 5명과 역할을 바꾸어 연습하고 각 연습의 보완점을 기록합니다. 실제 고객에게 보내는 메시지는 교육 화면에서 자동 발송하지 않습니다.", "flow": ["첫 연락", "거절 이해", "일정 합의", "5회 연습"], "practice": "동료 5명과의 TA 연습을 이름 대신 A~E로 구분해 날짜·보완점·다음 행동을 제출하세요.", "mentor_required": true, "quiz": [{"id": "q1", "question": "연락을 원하지 않는 고객에게는?", "options": ["계속 연락하면 설득된다고 생각한다", "의사를 존중하고 연락 계획에 반영한다"], "answer": 1, "explanation": "의사를 존중하고 연락 계획에 반영한다. 첫 연락에서 소개와 목적을 밝히고, 거절 이유가 시간인지 필요성인지 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 신입교육 비지니스 매너.pptx · 질문·경청·역할극 재구성"]}, {"id": "d15", "day": 15, "title": "생애주기와 사망 보장", "scenario": "가족을 위해 얼마를 준비해야 할까요?", "body": "가족의 생활비, 돌봄과 교육, 부채, 기존 준비를 구분해 질문합니다. 사망 담보는 일반·질병·상해·재해 등 이름과 정의, 제외 조건을 확인합니다. 정기와 종신은 보장기간 차이를 먼저 보고 납입과 해지 조건을 비교합니다. 누구에게나 같은 금액을 권하거나 보험을 저축과 동일하게 설명하지 않습니다.", "flow": ["가족의 필요", "기존 준비", "담보 정의", "기간·비용"], "practice": "가상 가족의 필요 자금과 기존 준비를 항목별로 구분하고 추가 질문 3개를 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "사망 보장을 비교할 때 필요한 것은?", "options": ["담보 정의와 기간, 가족 상황을 함께 확인한다", "가입금액이 큰 계약만 선택한다"], "answer": 0, "explanation": "담보 정의와 기간, 가족 상황을 함께 확인한다. 가족의 생활비, 돌봄과 교육, 부채, 기존 준비를 구분해 질문합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 신입교육 사망보험.pptx · 담보·기간 비교 주제 재구성"]}, {"id": "d16", "day": 16, "title": "갱신형·비갱신형과 유지 비용", "scenario": "지금 보험료가 싼 쪽이 항상 유리하죠?", "body": "갱신형은 갱신 시 보험료가 달라질 수 있으므로 주기와 종료 시점을 확인합니다. 비갱신형도 납입기간, 특약 구성, 변경 조건을 살펴야 합니다. 현재 보험료와 장래 가정에 따른 예시를 구분합니다. 예상표는 확정 보험료가 아니며 같은 기간과 보장 조건으로 비교해야 의미가 있습니다.", "flow": ["현재 보험료", "갱신 주기", "납입 기간", "가정 비교"], "practice": "동일한 비교 기간을 정하고 갱신·비갱신을 설명하는 1분 대본을 작성하세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "갱신 예상표를 보여줄 때는?", "options": ["미래 보험료가 확정됐다고 말한다", "가정과 실제 향후 보험료의 차이를 밝힌다"], "answer": 1, "explanation": "가정과 실제 향후 보험료의 차이를 밝힌다. 갱신형은 갱신 시 보험료가 달라질 수 있으므로 주기와 종료 시점을 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d17", "day": 17, "title": "치료비의 네 칸 읽기", "scenario": "암이면 모든 병원비를 5%만 내나요?", "body": "진료비는 일반 급여, 선별급여, 급여 전액본인부담, 비급여로 나누어 확인합니다. 암 산정특례의 5%는 적용 조건을 충족한 관련 급여 범위에 대한 안내이며 모든 진료비에 적용되지 않습니다. 영수증과 세부내역서의 분류를 읽은 뒤 민영보험의 지급 조건을 따로 확인합니다.", "flow": ["일반 급여", "선별급여", "전액본인부담", "비급여"], "practice": "가상 급여 100만원과 비급여 40만원을 구분해 설명하고 확인 질문 3개를 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "비급여에도 산정특례 5%를 일괄 적용할까요?", "options": ["적용하지 않고 분류와 조건을 확인한다", "암 치료이면 모두 적용한다"], "answer": 0, "explanation": "적용하지 않고 분류와 조건을 확인한다. 진료비는 일반 급여, 선별급여, 급여 전액본인부담, 비급여로 나누어 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 보험 자료 정리.pdf · 현장교육 재구성 원고"], "case_reading": "**오늘의 결과물:** 고객에게 산정특례와 비급여를 구분해 1분간 설명하고, 병원비 확인 질문 세 가지를 작성합니다.\n\n### 상황\n\n고객: “암이면 병원비를 전부 5%만 내면 되죠? 그럼 실손이나 다른 보장은 필요 없지 않나요?”\n\n### 먼저 이해하기\n\n진료비 영수증을 볼 때는 각각의 금액이 어떤 분류인지 살펴봅니다.\n\n| 분류 | 이해를 돕는 설명 | 상담에서 확인할 것 |\n|---|---|---|\n| 일반적인 급여 | 건강보험이 적용되는 진료 항목입니다. 환자 부담은 항목과 조건에 따라 다릅니다. | 해당 진료가 산정특례 대상 질환과 관련 있는지 |\n| 선별급여 | 건강보험의 별도 본인부담률이 적용되는 항목입니다. | 항목과 실제 본인부담률 |\n| 급여 전액본인부담 | 건강보험 체계상 항목이지만 비용 전액을 환자가 부담하는 경우입니다. | 병원 영수증에 어떤 항목으로 표시되는지 |\n| 비급여 | 건강보험 급여 적용 대상이 아닌 항목입니다. | 진료 내용과 금액, 해당 민영보험의 보장 조건 |\n\n암 산정특례는 조건을 충족한 대상자의 해당 질환 관련 **일부 본인부담 급여**에 적용됩니다. 국민건강보험공단 안내상 암의 본인부담률은 5%이며 적용 기간은 5년입니다. 선별급여, 전액본인부담, 비급여는 이 산정특례 적용 범위에서 제외됩니다. 즉, ‘암 치료비 전체의 5%’라고 설명하면 안 됩니다. 실제 적용 여부와 범위는 의료기관과 공단에서 확인합니다.\n\n### 설명 예시\n\n“암 산정특례 대상이면 해당 질환에 관련된 급여 중 적용되는 진료비는 본인부담이 줄어들 수 있습니다. 다만 선별급여나 비급여까지 모두 5%가 되는 것은 아니어서 영수증의 항목을 나눠 확인해야 합니다. 가입하신 보험에서 어떤 항목이 보장되는지도 약관을 함께 보겠습니다.”\n\n### 직접 해보기\n\n가상 영수증에 적용 대상인 급여 100만 원과 비급여 40만 원이 각각 표시되어 있다고 가정합니다. 급여 부분에 산정특례 5%가 적용된다면 그 급여에 대한 본인부담은 5만 원입니다. 이 예시에서 비급여 40만 원에 5%를 적용해 2만 원이라고 말할 수는 없습니다. 민영보험 지급액은 약관과 별도 조건 확인 전이므로 계산하지 않습니다.\n\n고객에게 할 질문 세 가지를 적어보세요.\n1. 진료비 영수증과 세부내역서에서 항목별 분류를 확인할 수 있을까요?\n2. 이 진료에 산정특례가 적용되었는지 의료기관이나 공단에 확인하셨나요?\n3. 가지고 계신 실손·진단비 특약의 증권과 약관을 함께 확인해도 될까요?\n\n**점검:** “암이면 모든 비용이 5%다”는 설명은 옳지 않습니다. 선배는 네 가지 분류를 구분했는지, 확인 전 보장이나 보험금 지급을 확정하지 않았는지 피드백합니다.\n\n**공식 근거:** [국민건강보험공단 산정특례 안내](https://www.nhis.or.kr/renewal_popup/poster/20260608_poster_longdesc_1.html) (적용 범위·암 본인부담률).\n", "reference_url": "https://www.nhis.or.kr/renewal_popup/poster/20260608_poster_longdesc_1.html", "image_b64": "", "image_caption": "제공 자료 · 급여와 비급여의 기본 구분. 세부 적용은 아래 사례에서 확인하세요."}, {"id": "d18", "day": 18, "title": "실손 1~5세대와 전환 비교", "scenario": "보험료가 낮으면 새 실손으로 바꿀까요?", "body": "세대 이름만으로 유불리를 정하지 않습니다. 가입 시기와 실제 약관에서 급여·비급여 범위, 자기부담, 갱신·재가입, 제외 조건을 비교합니다. 5세대는 급여와 중증·비중증 비급여를 구분하는 구조입니다. 기존 계약을 먼저 해지하지 않고 의료 이용과 전환 조건을 함께 확인합니다. 할인 제도의 예정 내용은 시행 확인 전 확정 조건처럼 설명하지 않습니다.", "flow": ["현재 계약", "보장 변화", "본인 부담", "전환 조건"], "practice": "현재 계약과 검토 계약을 비교할 항목 5개와 고객에게 물을 질문을 작성하세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "실손 전환 판단의 기준은?", "options": ["낮아진 보험료만 본다", "보험료·보장 변화·의료 이용을 함께 비교한다"], "answer": 1, "explanation": "보험료·보장 변화·의료 이용을 함께 비교한다. 세대 이름만으로 유불리를 정하지 않습니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 보험 자료 정리.pdf · 현장교육 재구성 원고"], "case_reading": "**오늘의 결과물:** 실손의 세 칸을 구분하고, 기존 계약자의 전환 여부를 판단하기 위해 무엇을 비교해야 하는지 설명합니다.\n\n### 상황\n\n고객: “보험료가 싸진다던데 기존 실손을 해지하고 바로 5세대로 바꾸는 게 좋겠죠?”\n\n### 먼저 이해하기\n\n2026년 5월 6일 출시된 5세대 실손은 급여 보장과 비급여 특약을 나누고 비급여를 중증·비중증으로 구분합니다. 아래는 금융위원회가 소개한 구조의 일부입니다. 본인의 계약에 적용할 때는 구체적 약관을 확인해야 합니다.\n\n| 구분 | 구조를 이해하는 핵심 | 확인할 것 |\n|---|---|---|\n| 급여 | 입원은 기존 보장 수준을 유지하고, 외래 자기부담은 건강보험 본인부담률과 연동합니다. | 입원·통원 여부, 의료기관, 실제 급여 및 공제 조건 |\n| 중증 비급여 특약 | 중증 관련 비급여를 별도 보장합니다. 상급종합병원·종합병원 입원 치료의 연간 자기부담 상한 500만 원이 신설됐습니다. | 해당 질환·치료·의료기관이 조건에 들어가는지 |\n| 비중증 비급여 특약 | 입원 자기부담률 50%, 통원은 50%와 5만 원 중 큰 금액을 적용하는 구조입니다. 연간·입원·통원 한도와 면책도 있습니다. | 보장 대상인지, 한도·공제·제외 사항 및 구체적 계약 조건 |\n\n연간 500만 원 상한은 모든 병원비 또는 모든 비급여에 적용되는 만능 상한이 아닙니다. 적용 범위와 예외는 약관을 확인합니다. 금융위원회가 제시한 보험료 감소는 비교 기준에 따른 예상치이므로 고객별 실제 보험료를 대신하지 않습니다.\n\n### 단순 계산 연습\n\n가상 사례: 5세대 비중증 비급여 특약에서 보장 대상인 입원 의료비가 100만 원이고, 공제·한도 등 다른 제한이 적용되지 않는다고 가정합니다. 입원 자기부담률이 50%라면 단순 계산상 자기부담은 50만 원, 보험금은 50만 원입니다. 실제 지급액은 치료의 보장 여부와 계약·면책·한도 등에 따라 달라집니다.\n\n### 전환 상담은 이렇게 시작합니다\n\n“보험료만 보면 결정하기 어렵습니다. 현재 계약의 보험료와 보장, 앞으로 예상하는 의료 이용, 바뀌는 자기부담과 제외 항목을 나란히 확인한 후 선택하시는 게 좋겠습니다. 현재 계약의 세대와 약관부터 확인해 볼까요?”\n\n**전환 전 비교표:** ① 기존 보험 가입 시기·특약·현재 보험료 ② 기존과 새 계약의 급여·비급여 범위 및 제외 항목 ③ 본인부담·한도 ④ 고객의 의료 이용 및 재정 상황 ⑤ 회사별 실제 전환 조건과 철회 가능 조건. 기존 계약 해지나 전환을 먼저 권유하지 않습니다.\n\n### 확인 문제\n\n1. 중증 비급여의 연 500만 원 자기부담 상한이 모든 의료비에 적용될까요? → 아니요. 금융위가 설명한 상급종합·종합병원 입원 등 적용 조건을 확인해야 합니다.\n2. 보험료가 낮다는 이유만으로 모두에게 전환을 권해도 될까요? → 아니요. 보장 변화와 고객 상황을 함께 비교해야 합니다.\n3. 비급여 100만 원이면 항상 50만 원을 지급할까요? → 아니요. 위의 계산은 보장 대상인 비중증 비급여 입원 및 다른 제한이 없다는 가정에 한정합니다.\n\n**선배 피드백:** 적용 조건을 설명했는가 / 기존 계약의 변화와 고객의 의료 이용을 질문했는가 / 확정적 권유나 보험금 보장을 피했는가.\n\n**공식 근거:** [금융위원회 5세대 실손 출시 및 보장 구조](https://www.fsc.go.kr/po010103/86831?srchKey=sj). 2026년 11월 예정된 초기 실손 관련 할인 제도는 시행 시점과 세부 조건을 재확인하기 전까지 확정 안내하지 않습니다.\n", "reference_url": "https://www.fsc.go.kr/po010103/86831?srchKey=sj"}, {"id": "d19", "day": 19, "title": "암·뇌·심: 진단명과 담보", "scenario": "뇌동맥류라는데 뇌졸중 진단비가 나오나요?", "body": "진단명, 확진 여부, 특약명, 약관의 대상 질병과 진단 요건을 구분합니다. 암·뇌·심장 관련 용어가 비슷해도 지급 범위는 같다고 볼 수 없습니다. 설계사가 검사를 해석해 진단하지 않고 계약 자료와 필요한 의료 서류를 확인합니다. 진단비와 치료비는 지급 사유를 각각 확인합니다.", "flow": ["진단 내용", "특약명", "보장 정의", "지급 요건"], "practice": "특약명·확인할 정의·추가 서류·확정할 수 없는 내용의 네 칸을 채우세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "병명만 듣고 지급을 확정할 수 있나요?", "options": ["진단 자료와 해당 특약의 조건을 확인한다", "질병 이름이 비슷하면 지급된다"], "answer": 0, "explanation": "진단 자료와 해당 특약의 조건을 확인한다. 진단명, 확진 여부, 특약명, 약관의 대상 질병과 진단 요건을 구분합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 보험 자료 정리.pdf · 현장교육 재구성 원고"], "case_reading": "**오늘의 결과물:** 뇌혈관 관련 고객 질문을 받고, 진단명·코드와 특약 정의를 확인하기 전에는 보장 여부를 단정하지 않습니다.\n\n### 상황\n\n고객: “건강검진에서 뇌동맥류라는 말을 들었는데, 제 뇌졸중 진단비가 나오나요?”\n\n### 설명의 순서\n\n1. 고객이 들은 의학적 용어와 현재 확진 여부를 확인합니다. 설계사가 검사 결과로 진단하지 않습니다.\n2. 고객의 동의를 받아 가입 증권에서 해당 특약명, 가입 시기, 보장금액을 찾습니다.\n3. 그 특약의 약관에서 보장하는 질병의 정의, 해당 진단 요건, 제외 및 지급 조건을 찾습니다. 같은 이름이라도 계약마다 다를 수 있습니다.\n4. 필요한 서류와 지급 여부는 해당 보험사에 확인합니다. 코드 하나만으로 자동 지급된다고 말하지 않습니다.\n5. 결과를 확인한 뒤 고객에게 근거와 다음 행동을 설명합니다.\n\n### 좋은 답변 예시\n\n“뇌동맥류라는 말씀만으로 뇌졸중 특약 지급 여부를 확정하기는 어렵습니다. 정확한 진단 내용과 가입하신 특약의 보장 정의를 함께 확인하고, 필요 서류와 지급 가능 여부를 보험사에 문의해 보겠습니다.”\n\n### 실습: 틀린 상담을 고쳐보세요\n\n- 잘못된 설명: “뇌혈관이라는 말이 있으니 무조건 지급됩니다.”\n- 고친 설명: “특약의 대상 질병과 진단 조건, 가입하신 계약을 확인해 보겠습니다.”\n- 잘못된 설명: “이 특약은 범위가 넓으니 무조건 갈아타세요.”\n- 고친 설명: “기존과 검토 중인 특약의 보장 범위·보험료·가입 조건을 함께 비교하겠습니다.”\n\n**제출 결과물:** 가상 증권을 보고 ‘특약명 / 약관에서 찾을 정의 / 추가 확인할 서류 / 아직 확정할 수 없는 내용’ 네 칸을 채웁니다. 실제 고객정보는 연습에 입력하지 않습니다.\n\n**선배 피드백:** 고객의 진단을 대신 내리지 않았는가 / 특약 정의와 지급 요건을 분리해 확인했는가 / 후속 확인 경로를 제시했는가.\n\n학습 근거: 제공 PDF 8·17·63쪽의 비교 아이디어를 활용했습니다. 각 질병코드의 포괄 범위나 상품별 지급 결과는 이 원고에서 검증·확정하지 않았습니다. 수업용 가상 약관과 예시는 배포 전 상품 담당자가 실제 약관을 기준으로 별도 검수해야 합니다.\n"}, {"id": "d20", "day": 20, "title": "수술·입원과 후유장해", "scenario": "수술했으니 모든 수술비가 나오겠죠?", "body": "수술의 의료적 명칭과 특약에서 정한 수술 정의·분류표를 나누어 봅니다. 1~5종과 다른 분류 체계를 같은 등급으로 대응시키지 않습니다. 입원 특약은 인정 조건과 일수, 병원 구분을 확인합니다. 후유장해는 진단명만으로 정하지 않고 약관상 상태와 판정 요건을 확인합니다.", "flow": ["수술 정의", "분류표", "입원 조건", "장해 판정"], "practice": "수술·입원·후유장해 각각에서 추가로 확인할 자료와 질문을 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "수술비 분류를 확인하는 기준은?", "options": ["다른 보험사의 인터넷 요약표", "가입한 특약의 정의와 분류표"], "answer": 1, "explanation": "가입한 특약의 정의와 분류표. 수술의 의료적 명칭과 특약에서 정한 수술 정의·분류표를 나누어 봅니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 신입교육 수술 입원.pptx · 특약별 분류 확인 주제 재구성"]}, {"id": "d21", "day": 21, "title": "3주차 실습: 가상 증권 분석", "scenario": "고객에게 현재 보장을 한 장으로 설명해 보세요.", "body": "가상 고객은 월 보험료 12만원, 20년 납입, 90세 만기이고 암 진단비 2천만원, 질병수술비 30만원이 표기돼 있습니다. 지급 조건과 실손 가입 여부는 제공되지 않았습니다. 이 사실과 미확인 정보를 분리해 보장분석표를 작성합니다. 가입금액을 실제 지급액처럼 설명하지 말고 추가 확인 순서를 제시합니다.", "flow": ["확인된 사실", "빠진 자료", "고객의 우선순위", "다음 확인"], "practice": "가상 증권 분석 결과와 1분 설명, 추가 자료 요청을 제출하세요. 팀장 검토가 필요한 주간 실습입니다.", "mentor_required": true, "quiz": [{"id": "q1", "question": "제시되지 않은 실손 가입 여부는?", "options": ["확인 필요로 남긴다", "대부분 가입하므로 있다고 입력한다"], "answer": 0, "explanation": "확인 필요로 남긴다. 가상 고객은 월 보험료 12만원, 20년 납입, 90세 만기이고 암 진단비 2천만원, 질병수술비 30만원이 표기돼 있습니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d22", "day": 22, "title": "자동차·운전자·배상책임", "scenario": "운전자보험이 있으니 자동차보험은 필요 없나요?", "body": "자동차보험과 운전자 비용 담보는 목적과 지급 조건을 구분합니다. 사고 상황, 피보험자, 담보, 면책을 확인하고 하나가 다른 하나를 전부 대신한다고 설명하지 않습니다. 일상생활배상책임도 사고 장소와 가족 범위, 자기부담, 중복 계약을 확인합니다. 여행자·단체보험은 대상자와 기간을 별도로 확인합니다.", "flow": ["사고 상황", "피보험자", "담보 범위", "면책·공제"], "practice": "가상 교통사고와 일상 사고에서 확인할 계약·자료를 구분해 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "비슷한 담보 이름의 계약을 비교할 때는?", "options": ["이름이 비슷하면 동일하다고 본다", "보장 대상과 지급 조건을 각각 확인한다"], "answer": 1, "explanation": "보장 대상과 지급 조건을 각각 확인한다. 자동차보험과 운전자 비용 담보는 목적과 지급 조건을 구분합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d23", "day": 23, "title": "치매·간병과 공적 장기요양", "scenario": "장기요양 등급을 받으면 보험금도 자동 지급되나요?", "body": "공적 장기요양의 신청·방문조사·등급 판정·서비스 이용과 민영보험 청구를 나눕니다. CDR과 장기요양 등급은 같은 지표가 아닙니다. 민영보험은 가입 특약의 판정 기준, 면책·감액, 서류를 확인합니다. 가족간병도 해당 계약이 정한 가족 범위와 간병 사실의 증빙 조건을 확인합니다.", "flow": ["공적 서비스", "등급·지표", "민영 특약", "청구 조건"], "practice": "돌봄 서비스와 보험금 청구로 나누어 고객이 다음에 할 행동을 작성하세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "장기요양 등급과 민영보험 청구는?", "options": ["각 절차와 계약 조건을 별도로 확인한다", "등급만 받으면 모든 보험이 지급된다"], "answer": 0, "explanation": "각 절차와 계약 조건을 별도로 확인한다. 공적 장기요양의 신청·방문조사·등급 판정·서비스 이용과 민영보험 청구를 나눕니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 보험 자료 정리.pdf · 현장교육 재구성 원고"], "case_reading": "**오늘의 결과물:** 공적 장기요양 절차와 민영보험 청구를 구분하고 고객이 다음에 할 일을 설명합니다.\n\n### 상황\n\n고객: “어머니가 집에서 돌봄이 필요해요. 장기요양 신청만 하면 제가 가입한 간병보험금도 자동으로 나오나요?”\n\n### 먼저 구분하기\n\n- **공적 장기요양:** 국민건강보험공단의 신청, 방문조사, 등급 판정과 서비스 이용 절차를 확인합니다. 서비스에는 재가급여와 시설급여 등이 있습니다.\n- **민영보험:** 가입한 상품의 지급 요건이 별도로 적용됩니다. 장기요양 등급을 지급 조건으로 삼는 특약도 있지만, 자동으로 모든 간병보험금이 지급되는 것은 아닙니다.\n- **가족간병 청구:** 실제 간병 사실뿐 아니라 해당 계약의 가족 인정 범위, 간병 시간, 서류와 보장 조건을 보험사에 확인합니다.\n\n### 설명 예시\n\n“장기요양 서비스 이용을 위한 공단 절차와 가입하신 민영보험 청구는 따로 확인해야 합니다. 먼저 공단에 신청 절차를 문의하고, 보험은 증권과 약관에서 어떤 상황이 지급 대상인지 확인해 보겠습니다. 청구에 필요한 서류도 보험사에 확인해 안내드릴게요.”\n\n### 연습: 다음 행동 세 가지\n\n1. 고객이 원하는 도움을 구분합니다: 일상 돌봄 서비스인지, 입원 중 간병비 청구인지.\n2. 공적 서비스는 공단의 신청 및 판정 절차와 이용 가능한 서비스를 확인합니다.\n3. 민영보험은 계약별 특약·지급 요건·청구 서류와 확인 창구를 정리합니다.\n\n청구 과정에서 동의서나 위임장을 요청받으면 서명 전 문서의 목적·범위와 상대방을 이해하고 확인하도록 안내합니다. 어떤 문서는 무조건 서명해도 된다거나 무조건 거부해야 한다고 일반화하지 않습니다.\n\n**선배 피드백:** 공적 제도와 민영보험을 구분했는가 / 필요 정보를 실제 확인할 기관에 연결했는가 / 고객에게 지급을 확약하지 않았는가.\n\n**공식 근거:** [국민건강보험공단 장기요양보험 운영 체계](https://www.nhis.or.kr/announce/wbhaec11100m01.do).\n", "reference_url": "https://www.nhis.or.kr/announce/wbhaec11100m01.do"}, {"id": "d24", "day": 24, "title": "보험금 청구와 사후관리", "scenario": "병원 서류를 무엇부터 준비해야 하나요?", "body": "보험사, 청구 사유, 진료 내용을 확인하고 최신 청구 안내와 계약을 대조합니다. 서류의 명칭만 보고 진단명·코드·치료 내용이 모두 있다고 가정하지 않습니다. 비용이 드는 서류는 필요한 항목을 먼저 확인합니다. 제출 뒤 접수 여부와 추가 요청을 안내하고 지급 결정 전에는 확약하지 않습니다.", "flow": ["청구 사유", "필요 항목", "안전한 제출", "접수·후속"], "practice": "가상 통원 청구의 서류 확인 질문과 접수 후 안내 문자를 작성하세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "유료 서류 발급을 안내하기 전에는?", "options": ["모든 고객에게 같은 서류를 발급받게 한다", "보험사에 필요한 항목과 대체 서류를 확인한다"], "answer": 1, "explanation": "보험사에 필요한 항목과 대체 서류를 확인한다. 보험사, 청구 사유, 진료 내용을 확인하고 최신 청구 안내와 계약을 대조합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d25", "day": 25, "title": "비교표와 제안서 만들기", "scenario": "보험료를 줄이면 무엇이 달라지나요?", "body": "현재 유지, 일부 조정, 새 계약 검토의 선택지를 같은 기준으로 비교합니다. 월 보험료, 보장 범위, 납입·보장기간, 갱신, 제외·감액, 기존 계약 변경의 불이익을 함께 제시합니다. 확인되지 않은 수치를 유리하게 채우지 않습니다. 해지와 신규 가입의 순서, 가입 가능 여부를 확인한 뒤 고객이 선택하도록 설명합니다.", "flow": ["현재 유지", "조정안", "새 계약 검토", "변화 설명"], "practice": "가상 고객에게 유지안과 조정안의 장단점을 나누어 설명하는 제안서를 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "비교표에서 빠뜨리기 쉬운 항목은?", "options": ["기존 계약 변경의 불이익과 제외 조건", "새 계약의 장점만 강조하는 문구"], "answer": 0, "explanation": "기존 계약 변경의 불이익과 제외 조건. 현재 유지, 일부 조정, 새 계약 검토의 선택지를 같은 기준으로 비교합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d26", "day": 26, "title": "변액·금리와 장기 계획", "scenario": "예시 수익률이면 그만큼 받는 거죠?", "body": "보장과 투자 성격, 비용, 운용 결과에 따른 변동을 분리해 읽습니다. 예시 수익률은 확정 수익률이 아닙니다. 금리 하나로 미래 결과를 단정하지 않고 고객의 목적·기간·손실 감내 여부를 확인합니다. 취급에 필요한 자격과 권한은 회사 기준에 따라 확인합니다. 단기 자금과 장기 계획을 섞어 제안하지 않습니다.", "flow": ["목적·기간", "비용", "변동 가능성", "자격·권한"], "practice": "가상 고객의 단기·중기·장기 목적을 나누고 확인 질문을 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "예시 수익률을 설명할 때는?", "options": ["계속 같은 수익이 난다고 안내한다", "확정 수익이 아니며 비용·위험을 함께 설명한다"], "answer": 1, "explanation": "확정 수익이 아니며 비용·위험을 함께 설명한다. 보장과 투자 성격, 비용, 운용 결과에 따른 변동을 분리해 읽습니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d27", "day": 27, "title": "시책·컨벤션과 활동 계획", "scenario": "이번 달 조건을 어디에서 확인하나요?", "body": "시책과 컨벤션은 적용 월, 대상, 인정 기준, 지급·환수 조건을 공식 공지에서 확인합니다. 예전 자료의 수당률이나 기준을 그대로 쓰지 않습니다. 고객에게 필요한 계약인지 판단하는 과정과 개인 보상 목표를 구분합니다. WORKSPACE 계산기는 입력값과 공지 기준을 확인하는 보조 도구로 사용합니다.", "flow": ["적용 월", "대상·인정", "지급·환수", "활동 계획"], "practice": "현재 공지에서 확인할 항목 목록과 고객 관점의 주간 활동 계획을 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "시책 계산 전에 필요한 것은?", "options": ["현재 공지의 적용 조건 확인", "지난달 기준을 그대로 적용"], "answer": 0, "explanation": "현재 공지의 적용 조건 확인. 시책과 컨벤션은 적용 월, 대상, 인정 기준, 지급·환수 조건을 공식 공지에서 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d28", "day": 28, "title": "선배 동행과 현장 관찰", "scenario": "실제 상담에서 무엇을 관찰해야 할까요?", "body": "상담 전 선배와 자신의 역할을 합의하고 고객의 동의를 확인합니다. 관찰 기록은 이름·병력·연락처 없이 질문 방식과 설명 순서에 집중합니다. 서로 다른 선배 5명과의 동행 기회를 계획하고 완료한 활동만 기록합니다. 동행이 어려우면 미완료로 남기고 다음 일정을 정합니다. 역할극은 실제 동행으로 표시하지 않습니다.", "flow": ["사전 역할", "동의", "관찰", "복기"], "practice": "동행 5회의 날짜·익명 선배 구분·관찰점·다음 연습을 적으세요. 아직 못 한 활동은 일정으로 구분하세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "동행을 못 했다면 기록은?", "options": ["역할극을 실제 동행으로 기록한다", "미완료와 다음 일정을 사실대로 적는다"], "answer": 1, "explanation": "미완료와 다음 일정을 사실대로 적는다. 상담 전 선배와 자신의 역할을 합의하고 고객의 동의를 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}, {"id": "d29", "day": 29, "title": "거절 대응과 다음 상담", "scenario": "생각해 보고 연락할게요.", "body": "지금 결정이 어려운 이유를 여쭤봐도 되는지 확인합니다. 비용·필요성·신뢰·시간에 따라 필요한 정보가 다릅니다. 충분히 설명한 뒤 고객이 선택할 시간을 줍니다. 재연락 날짜와 방법은 고객 의사에 따라 합의하며 거절을 실패로 몰아붙이지 않습니다. 후속 기록에는 사실과 약속만 남깁니다.", "flow": ["이유 확인", "정보 보완", "선택 존중", "후속 합의"], "practice": "비용·시간·필요성 거절에 각각 답할 문장과 후속 약속 예시를 적으세요.", "mentor_required": false, "quiz": [{"id": "q1", "question": "거절 뒤 다음 행동은?", "options": ["고객이 원하는 후속 여부를 확인한다", "즉시 결정할 때까지 설득한다"], "answer": 0, "explanation": "고객이 원하는 후속 여부를 확인한다. 지금 결정이 어려운 이유를 여쭤봐도 되는지 확인합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성", "사용자 제공: 신입교육 비지니스 매너.pptx · 질문·경청·역할극 재구성"]}, {"id": "d30", "day": 30, "title": "30일 종합 실습과 다음 목표", "scenario": "첫 연락부터 사후관리까지 한 번에 진행해 보세요.", "body": "가상 고객은 보험료가 부담되고 가족 보장을 걱정합니다. 첫 연락, 상황 질문, 자료 확인, 분석 설명, 선택지 비교, 후속 약속을 순서대로 작성합니다. 지난 주간 피드백에서 고친 내용을 표시합니다. 모든 일차의 이해 확인과 실습을 마친 뒤 주간 검토 4개가 승인되면 초기 공통 과정 수료로 표시합니다. 이는 회사 위촉·자격 취득을 대신하지 않습니다.", "flow": ["연락·질문", "분석·비교", "후속 약속", "60·90일 목표"], "practice": "종합 상담 대본, 수정한 피드백, 60일·90일 목표와 관심 분야를 제출하세요.", "mentor_required": true, "quiz": [{"id": "q1", "question": "초기 과정 수료의 의미는?", "options": ["모든 상품 판매 자격을 취득한 상태", "정해진 학습과 실습 검토를 완료한 상태"], "answer": 1, "explanation": "정해진 학습과 실습 검토를 완료한 상태. 가상 고객은 보험료가 부담되고 가족 보장을 걱정합니다."}], "deepening": "기본 학습 후 30분 추가: 관련 자료에서 설명의 근거를 찾아 표시합니다(15분). 동료와 고객·설계사 역할을 바꿔 연습하고, 빠진 확인과 다음 행동을 기록합니다(15분).", "sources": ["사용자 제공: 신입 시스템 만들기(1).xlsx · 30일 업무 목록을 학습 순서로 재구성"]}], "published": true, "revision": 1, "updated_on": "2026-10-30", "learning_mode": "practice", "pass_percent": 100}'::jsonb) on conflict(id) do nothing;
